verify:
def skill():
    x = Symbol('x')
    h = x**3 - 3*x**2 - 9*x + 30
    return sum(h.subs(x, c) for c in solve(diff(h, x), x))

def standard():
    x, k = symbols('x k')
    p = x**3 - 3*x**2 + 30 - (9*x + k)
    ks = [v for v in solve(discriminant(p, x), k) if v.is_real]
    for v in ks:
        assert len(set(real_roots(Poly(p.subs(k, v), x)))) == 2
    return sum(ks)

def unique():
    return [standard()]
